417	# This function unpacks a tensordesc object into its components:
418	# - data pointer
419	# - shape dimensions
420	# - stride values
421	def make_tensordesc_arg(arg):
422	    assert isinstance(arg, TensorDescriptor)
423	    data_ptr = arg.base.data_ptr()
424	    shape = arg.shape
425	    strides = arg.strides
426	    # Currently only contiguous tensors are supported
427	    assert strides[-1] == 1
428	    # The 0 is a placeholder that replaces the tensordesc type when passing to kernel.
429	    # nvidia oss backend passes tensordesc directly, but tileir needs to decompose it.
430	    result = [0, data_ptr, *shape, *strides]
431	    return result
