464	class TileIRLauncher(object):
465	    def __init__(self, src, metadata):
466	        ids = {
467	            "ids_of_const_exprs": src.fn.constexprs if hasattr(src, "fn") else tuple()
468	        }
469	
470	        constants = src.constants if hasattr(src, "constants") else dict()
471	        arg_idx = lambda x: (src.fn.arg_names.index(x),) if isinstance(x, str) else x
472	        constants = {arg_idx(idx): value for idx, value in constants.items()}
473	        signature = {idx: value for idx, value in src.signature.items()}
474	        def is_tensordesc(value):
475	            return isinstance(value, str) and value.startswith("tensordesc")
476	
477	        def contains_tensordesc(value):
478	            if isinstance(value, tuple):
479	                return any(contains_tensordesc(element) for element in value)
480	            return is_tensordesc(value)
481	
482	        def expand_tensordesc(value):
483	            shape_str = value.split("[", 1)[1].split("]", 1)[0]
484	            shape = [int(s) for s in shape_str.split(",")]
485	            dtype = value.split("<", 1)[1].split("[", 1)[0]
486	            return ["i32", f"*{dtype}", *(["i32"] * len(shape)), *(["i64"] * len(shape))]
487	
488	        def expand_tuple(value):
489	            result = []
490	            for element in value:
491	                if is_tensordesc(element):
492	                    result.extend(expand_tensordesc(element))
493	                elif isinstance(element, tuple):
494	                    result.append(expand_tuple(element))
495	                else:
496	                    result.append(element)
497	            return tuple(result)
498	
499	        has_tensordesc = any(contains_tensordesc(value) for value in signature.values())
500	        self.ori_signature_len = len(signature)
501	        if has_tensordesc:
502	            # Convert tensor descriptors to [placeholder, ptr, shape and stride].
503	            # Nested descriptors are expanded in place so the generated launcher
504	            # retains the original tuple structure.
505	            post_signature = {}
506	            for key, value in src.signature.items():
507	                key = arg_idx(key)
508	                if is_tensordesc(value):
509	                    for idx, expanded_type in enumerate(expand_tensordesc(value)):
510	                        post_signature[f"{key}_tensordesc_{idx}"] = expanded_type
511	                elif isinstance(value, tuple):
512	                    post_signature[key] = expand_tuple(value)
513	                else:
514	                    post_signature[key] = value
515	            self.signature = post_signature
516	        else:
517	            self.signature = signature
518	        self.constants = constants
519	        src = make_launcher(self.constants, self.signature)
520	        mod = compile_module_from_src(
521	            src, "__triton_launcher", library_dirs(), include_dirs, libraries
522	        )
523	        if has_tensordesc:
524	            self.launch = wrap_handle_tensordesc(mod.launch)
525	        else:
526	            self.launch = mod.launch
527	        self.launch_pdl = metadata.launch_pdl
528	
529	    def __call__(self, *args, **kwargs):
530	        # TODO: below if branch is for torch 2.8.0a0+5228986c39.nvinternal commit
531	        # where constexpr arguments are not passed to the launch function by inductor
532	        # remove this after torch
533	        # 9 is the number of metadata arguments in `src` defined in `make_launcher`
